package io.aetherdb.codec;
import io.aetherdb.api.typed.ValueCodec;import java.nio.*;import java.nio.charset.StandardCharsets;import java.util.Arrays;
public final class TypedValueEnvelope{public static final int HEADER_BYTES=40;private TypedValueEnvelope(){}public static <V>byte[]encode(ValueCodec<V>c,V value){if(value==null)throw new IllegalArgumentException("null values are forbidden");byte[]payload=c.encode(value);if(payload==null||payload.length>c.maximumEncodedSize(value))throw new IllegalArgumentException("encoded value exceeds codec bound");ByteBuffer b=ByteBuffer.allocate(HEADER_BYTES+payload.length).order(ByteOrder.BIG_ENDIAN);b.put("AETV".getBytes(StandardCharsets.US_ASCII)).putShort((short)1).putShort((short)HEADER_BYTES).putLong(c.schemaId().getMostSignificantBits()).putLong(c.schemaId().getLeastSignificantBits()).putInt(c.currentSchemaVersion()).putInt(0).putInt(payload.length).putInt(0).put(payload);return b.array();}public static <V>V decode(ValueCodec<V>c,byte[]in){if(in==null||in.length<HEADER_BYTES)throw invalid();ByteBuffer b=ByteBuffer.wrap(in).order(ByteOrder.BIG_ENDIAN);byte[]m=new byte[4];b.get(m);if(!Arrays.equals(m,"AETV".getBytes(StandardCharsets.US_ASCII))||b.getShort()!=1||b.getShort()!=HEADER_BYTES||b.getLong()!=c.schemaId().getMostSignificantBits()||b.getLong()!=c.schemaId().getLeastSignificantBits())throw invalid();int version=b.getInt(),flags=b.getInt(),length=b.getInt(),reserved=b.getInt();if(flags!=0||reserved!=0||length!=b.remaining())throw invalid();byte[]payload=new byte[length];b.get(payload);return c.decode(version,payload);}private static IllegalArgumentException invalid(){return new IllegalArgumentException("invalid typed value envelope");}}
